// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ───────────────────────────────────────────────────────────
 // paraboloid bowl   -> BufferGeometry (r,θ) grid, vertexColors cream/blue/orange, MeshBasicMaterial DoubleSide 0.96
 // top rim           -> TubeGeometry circle r=2.6 z=3.38, gray #8899a5
 // level curve       -> TubeGeometry circle r=2.012 z=2.025, teal #1E8A7C
 // z / y / x axes    -> Cylinder shaft + Cone head, black; buried parts LineDashedMaterial gray #999
 // P0 dot            -> SphereGeometry(0.09) black
 // ∇f arrow          -> cylinder+cone orange #EA6A2A, tangent up-slope, len 1.5
 // −∇f arrow         -> cylinder+cone dark blue #1F3E8C, tangent down-slope, len 1.5
 // level arrows (x2) -> cylinder+cone teal #1E8A7C, ±t̂, len 1.0
 // u arrow           -> cylinder+cone purple #7B2CBF (surface copy + plane copy)
 // drop lines        -> Line + LineDashedMaterial red #E03030 (P0, ∇f tip) / gray #999 (others)
 // plane diagram     -> quad outline Line black, 0.8-scale arrow set, 0.18 right-angle marker
 // leader lines      -> Line black
 // all text          -> addLabel HTML
 ────────────────────────────────────────────────────────────────────────── */

/* math (x,y,z  z-up) -> three (y, z, x) so +y is screen-right, +x comes forward-left */
const M = (x, y, z) => new THREE.Vector3(y, z, x);
const YUP = new THREE.Vector3(0, 1, 0);

const gSurf  = new THREE.Group(); scene.add(gSurf);   // surface arrow set (fades)
const gPlane = new THREE.Group(); scene.add(gPlane);  // flattened diagram (fades)
const gDrops = new THREE.Group(); scene.add(gDrops);  // dashed drop lines
const gStatic= new THREE.Group(); scene.add(gStatic); // bowl, axes, dot

/* ── helpers ─────────────────────────────────────────────────────────────── */
function lineOf(pts, color, o = {}) {
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = o.dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: o.dashSize || 0.13, gapSize: o.gapSize || 0.1, transparent: true })
    : new THREE.LineBasicMaterial({ color, transparent: true });
  const l = new THREE.Line(geo, mat);
  if (o.dashed) l.computeLineDistances();
  return l;
}
function segMesh(a, b, r, color) {
  const dir = b.clone().sub(a); const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 12),
    new THREE.MeshBasicMaterial({ color, transparent: true }));
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(YUP, dir.normalize());
  return m;
}
function coneMesh(tip, dir, len, r, color) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(r, len, 18),
    new THREE.MeshBasicMaterial({ color, transparent: true }));
  const d = dir.clone().normalize();
  m.position.copy(tip).addScaledVector(d, -len / 2);
  m.quaternion.setFromUnitVectors(YUP, d);
  return m;
}
function makeArrow(len, color, opt = {}) {
  const headLen = opt.headLen ?? 0.3, headR = opt.headR ?? 0.105, shaftR = opt.shaftR ?? 0.038;
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true });
  const g = new THREE.Group();
  const sl = Math.max(len - headLen, 0.001);
  const sh = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, sl, 14), mat); sh.position.y = sl / 2;
  const hd = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 18), mat); hd.position.y = sl + headLen / 2;
  g.add(sh, hd); g.userData.mat = mat;
  return g;
}
function placeArrow(g, origin, dir) {
  g.position.copy(origin);
  g.quaternion.setFromUnitVectors(YUP, dir.clone().normalize());
}
function circlePts(radius, z, n = 120) {
  const a = [];
  for (let i = 0; i < n; i++) { const t = 2 * Math.PI * i / n; a.push(M(radius * Math.cos(t), radius * Math.sin(t), z)); }
  return a;
}
function tubeCircle(radius, z, tubeR, color) {
  const curve = new THREE.CatmullRomCurve3(circlePts(radius, z), true);
  return new THREE.Mesh(new THREE.TubeGeometry(curve, 200, tubeR, 8, true),
    new THREE.MeshBasicMaterial({ color, transparent: true }));
}

/* ── paraboloid bowl  z = 0.5(x²+y²), r ≤ 2.6 ────────────────────────────── */
const RB = 2.6, ZRIM = 0.5 * RB * RB;
{
  const NR = 44, NT = 120;
  const pos = [], col = [], idx = [];
  const cream = new THREE.Color('#F7EFD9'), blueT = new THREE.Color('#8FB8DC'), blueD = new THREE.Color('#6E9BC8');
  const or1 = new THREE.Color('#E8703A'), or2 = new THREE.Color('#F09A6A');
  for (let i = 0; i <= NR; i++) {
    const r = RB * i / NR;
    for (let j = 0; j <= NT; j++) {
      const th = 2 * Math.PI * j / NT;
      const p = M(r * Math.cos(th), r * Math.sin(th), 0.5 * r * r);
      pos.push(p.x, p.y, p.z);
      const s = 0.5 * (1 + Math.sin(th));                    // 0 left(cream) .. 1 right(blue)
      const top = cream.clone().lerp(blueT.clone().lerp(blueD, 0.35 * s), s);
      const bot = or1.clone().lerp(or2, s);
      let t = (r / RB - 0.28) / 0.62; t = Math.min(1, Math.max(0, t)); t = t * t * (3 - 2 * t);
      const c = bot.clone().lerp(top, t);
      col.push(c.r, c.g, c.b);
    }
  }
  for (let i = 0; i < NR; i++) for (let j = 0; j < NT; j++) {
    const a = i * (NT + 1) + j, b = a + 1, c = a + NT + 1, dd = c + 1;
    idx.push(a, c, b, b, c, dd);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  geo.setIndex(idx); geo.computeVertexNormals();
  const bowl = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({
    vertexColors: true, side: THREE.DoubleSide, transparent: true, opacity: 0.96,
    polygonOffset: true, polygonOffsetFactor: 2, polygonOffsetUnits: 2
  }));
  gStatic.add(bowl);
  gStatic.add(tubeCircle(RB, ZRIM, 0.013, '#8899a5'));
}

/* ── axes ────────────────────────────────────────────────────────────────── */
const AX = 3.4, AR = 0.016, HL = 0.3, HR = 0.1;
// z axis (0 -> 4.3) + gray dashed continuation below origin
gStatic.add(segMesh(M(0, 0, 0), M(0, 0, 4.0), AR, 0x000000));
gStatic.add(coneMesh(M(0, 0, 4.3), M(0, 0, 1), HL, HR, 0x000000));
gStatic.add(lineOf([M(0, 0, 0), M(0, 0, -2.1)], 0x999999, { dashed: true }));
// y axis to the right (dashed where buried under the bowl)
gStatic.add(lineOf([M(0, 0, 0), M(0, 1.7, 0)], 0x999999, { dashed: true }));
gStatic.add(segMesh(M(0, 1.65, 0), M(0, AX - HL, 0), AR, 0x000000));
gStatic.add(coneMesh(M(0, AX, 0), M(0, 1, 0), HL, HR, 0x000000));
// x axis forward-left
gStatic.add(lineOf([M(0, 0, 0), M(1.7, 0, 0)], 0x999999, { dashed: true }));
gStatic.add(segMesh(M(1.65, 0, 0), M(AX - HL, 0, 0), AR, 0x000000));
gStatic.add(coneMesh(M(AX, 0, 0), M(1, 0, 0), HL, HR, 0x000000));

/* ── P0, gradient frame ──────────────────────────────────────────────────── */
