// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ───────────────────────────────────────────────────────────
 // paraboloid exterior -> BufferGeometry (r,θ) grid, BackSide, vertexColors saturated orange with cream/blue rim band
 // paraboloid interior -> same grid, FrontSide, vertexColors cream(left)→blue(right)
 // top rim             -> TubeGeometry circle r=2.6 z=3.38, gray #8899a5
 // level curve         -> TubeGeometry circle r=2.012 z=2.025, teal #1E8A7C
 // z / y / x axes      -> Cylinder shaft + Cone head, black; buried parts LineDashedMaterial gray #999
 // P0 dot              -> SphereGeometry(0.09) black
 // ∇f arrow            -> cylinder+cone orange #EA6A2A, tangent up-slope, len 2.0 (past the rim)
 // −∇f arrow           -> cylinder+cone dark blue #1F3E8C, tangent down-slope, len 1.7
 // level arrows (x2)   -> cylinder+cone teal #1E8A7C, ±t̂, len 1.15
 // u arrow             -> cylinder+cone purple #7B2CBF, short (1.15), offset outward (surface + plane copy)
 // drop lines          -> Line + LineDashedMaterial red #E03030 (P0, ∇f tip) / gray #999 (others)
 // plane diagram       -> quad outline Line black, 0.8-scale arrow set, 0.18 right-angle marker
 // leader lines        -> Line black
 // all text            -> addLabel HTML (incl. ∇f / −∇f on the surface arrows)
 ────────────────────────────────────────────────────────────────────────── */

/* math (x,y,z  z-up) -> three (y, z, x) so +y is screen-right, +x comes forward-left */
const M = (x, y, z) => new THREE.Vector3(y, z, x);
const YUP = new THREE.Vector3(0, 1, 0);
const smoothstep = (a, b, t) => { let u = (t - a) / (b - a); u = Math.min(1, Math.max(0, u)); return u * u * (3 - 2 * u); };

const gSurf  = new THREE.Group(); scene.add(gSurf);   // surface arrow set (fades)
const gPlane = new THREE.Group(); scene.add(gPlane);  // flattened diagram (fades)
const gDrops = new THREE.Group(); scene.add(gDrops);  // dashed drop lines
const gStatic= new THREE.Group(); scene.add(gStatic); // bowl, axes, dot

/* ── helpers ─────────────────────────────────────────────────────────────── */
function lineOf(pts, color, o = {}) {
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = o.dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: o.dashSize || 0.13, gapSize: o.gapSize || 0.1, transparent: true })
    : new THREE.LineBasicMaterial({ color, transparent: true });
  const l = new THREE.Line(geo, mat);
  if (o.dashed) l.computeLineDistances();
  return l;
}
function segMesh(a, b, r, color) {
  const dir = b.clone().sub(a); const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 12),
    new THREE.MeshBasicMaterial({ color, transparent: true }));
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(YUP, dir.normalize());
  return m;
}
function coneMesh(tip, dir, len, r, color) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(r, len, 18),
    new THREE.MeshBasicMaterial({ color, transparent: true }));
  const d = dir.clone().normalize();
  m.position.copy(tip).addScaledVector(d, -len / 2);
  m.quaternion.setFromUnitVectors(YUP, d);
  return m;
}
function makeArrow(len, color, opt = {}) {
  const headLen = opt.headLen ?? 0.3, headR = opt.headR ?? 0.105, shaftR = opt.shaftR ?? 0.038;
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true });
  const g = new THREE.Group();
  const sl = Math.max(len - headLen, 0.001);
  const sh = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, sl, 14), mat); sh.position.y = sl / 2;
  const hd = new THREE.Mesh(new THREE.ConeGeometry(headR, headLen, 18), mat); hd.position.y = sl + headLen / 2;
  g.add(sh, hd); g.userData.mat = mat;
  return g;
}
function placeArrow(g, origin, dir) {
  g.position.copy(origin);
  g.quaternion.setFromUnitVectors(YUP, dir.clone().normalize());
}
function circlePts(radius, z, n = 140) {
  const a = [];
  for (let i = 0; i < n; i++) { const t = 2 * Math.PI * i / n; a.push(M(radius * Math.cos(t), radius * Math.sin(t), z)); }
  return a;
}
function tubeCircle(radius, z, tubeR, color) {
  const curve = new THREE.CatmullRomCurve3(circlePts(radius, z), true);
  return new THREE.Mesh(new THREE.TubeGeometry(curve, 220, tubeR, 8, true),
    new THREE.MeshBasicMaterial({ color, transparent: true }));
}

/* ── paraboloid bowl  z = 0.5(x²+y²), r ≤ 2.6 ────────────────────────────── */
const RB = 2.6, ZRIM = 0.5 * RB * RB;
{
  const NR = 52, NT = 144;
  const pos = [], cIn = [], cOut = [], idx = [];
  const cream = new THREE.Color('#F7EFD9');
  const blueT = new THREE.Color('#9CC2E2'), blueD = new THREE.Color('#6E9BC8');
  const orDark = new THREE.Color('#DD5A20'), orLite = new THREE.Color('#F0905A');
  const tmp = new THREE.Color();
  for (let i = 0; i <= NR; i++) {
    const r = RB * i / NR;
    for (let j = 0; j <= NT; j++) {
      const th = 2 * Math.PI * j / NT;
      const p = M(r * Math.cos(th), r * Math.sin(th), 0.5 * r * r);
      pos.push(p.x, p.y, p.z);
      const s = 0.5 * (1 + Math.sin(th));                      // 0 = left (cream), 1 = right (blue)
      // pale rim tint (interior colour everywhere, exterior only near the rim)
      const pale = cream.clone().lerp(blueT.clone().lerp(blueD, s), s);
      // interior: pale, slightly deeper toward the bottom of the bowl
      tmp.copy(pale).multiplyScalar(0.90);
      const inner = tmp.clone().lerp(pale, Math.min(1, r / RB + 0.25));
      cIn.push(inner.r, inner.g, inner.b);
      // exterior: saturated orange, blending to the pale band only just under the rim
      const orange = orDark.clone().lerp(orLite, s);
      const t = smoothstep(0.80, 0.985, r / RB);
      const outer = orange.lerp(pale, t);
      cOut.push(outer.r, outer.g, outer.b);
    }
  }
  for (let i = 0; i < NR; i++) for (let j = 0; j < NT; j++) {
    const a = i * (NT + 1) + j, b = a + 1, c = a + NT + 1, dd = c + 1;
    idx.push(a, c, b, b, c, dd);
  }
  const posAttr = new THREE.Float32BufferAttribute(pos, 3);
  const geoIn = new THREE.BufferGeometry();
  geoIn.setAttribute('position', posAttr);
  geoIn.setAttribute('color', new THREE.Float32BufferAttribute(cIn, 3));
  geoIn.setIndex(idx.slice()); geoIn.computeVertexNormals();
  const geoOut = new THREE.BufferGeometry();
  geoOut.setAttribute('position', posAttr);
  geoOut.setAttribute('color', new THREE.Float32BufferAttribute(cOut, 3));
  geoOut.setIndex(idx.slice()); geoOut.computeVertexNormals();

  const matIn = new THREE.MeshBasicMaterial({
    vertexColors: true, side: THREE.FrontSide,
    polygonOffset: true, polygonOffsetFactor: 3, polygonOffsetUnits: 3
  });
  const matOut = new THREE.MeshBasicMaterial({
    vertexColors: true, side: THREE.BackSide,
    polygonOffset: true, polygonOffsetFactor: 3, polygonOffsetUnits: 3
  });
  gStatic.add(new THREE.Mesh(geoIn, matIn));
  gStatic.add(new THREE.Mesh(geoOut, matOut));
  gStatic.add(tubeCircle(RB, ZRIM, 0.014, '#8899a5'));
}

/* ── axes ────────────────────────────────────────────────────────────────── */
const AX = 3.4, AR = 0.016, HL = 0.3, HR = 0.1;
// z axis + gray dashed continuation below origin
gStatic.add(segMesh(M(0, 0, 0), M(0, 0, 4.0), AR, 0x000000));
gStatic.add(coneMesh(M(0, 0, 4.3), M(0, 0, 1), HL, HR, 0x000000));
gStatic.add(lineOf([M(0, 0, 0), M(0, 0, -2.1)], 0x999999, { dashed: true }));
// y axis to the right (dashed where buried under the bowl)
gStatic.add(lineOf([M(0, 0, 0), M(0, 1.7, 0)], 0x999999, { dashed: true }));
gStatic.add(segMesh(M(0, 1.65, 0), M(0, AX - HL, 0), AR, 0x000000));
gStatic.add(coneMesh(M(0, AX, 0), M(0, 1, 0), HL, HR, 0x000000));
// x axis forward-left
gStatic.add(lineOf([M(0, 0, 0), M(1.7, 0, 0)], 0x999999, { dashed: true }));
gStatic.add(segMesh(M(1.65, 0, 0), M(AX - HL, 0, 0), AR, 0x000000));
gStatic.add(coneMesh(M(AX, 0, 0), M(1, 0, 0), HL, HR, 0x000000));

/* ── P0, gradient frame ──────────────────────────────────────────────────── */
const P0 = { x: 0.9, y: 1.8, z: 2.025 };
const GMAG = Math.hypot(P0.x, P0.y);                 // |∇f| ≈ 2.0125
const gh = [P0.x / GMAG, P0.y / GMAG];               // (0.447, 0.894)
const th_ = [-gh[1], gh[0]];                         // (-0.894, 0.447)
const P0v = M(P0.x, P0.y, P0.z);
const nOutM = new THREE.Vector3(P0.x, P0.y, -1).normalize();          // math-space outward normal
const nOut3 = M(nOutM.x, nOutM.y, nOutM.z).normalize();
const ORG = P0v.clone().addScaledVector(nOut3, 0.06);
const ORG_U = P0v.clone().addScaledVector(nOut3, 0.20);               // u sits in front of ∇f

const COL = { orange: 0xEA6A2A, blue: 0x1F3E8C, teal: 0x1E8A7C, purple: 0x7B2CBF };
const HI  = { orange: 0xFFA25C, blue: 0x5A7FE0, teal: 0x3FD3BE, purple: 0xB36BEE };

// tangent (math) of steepest ascent
const ascM = new THREE.Vector3(gh[0], gh[1], GMAG).normalize();
const ascDir = M(ascM.x, ascM.y, ascM.z).normalize();
const tanDir = M(th_[0], th_[1], 0).normalize();
const LUP = 2.0, LDN = 1.7, LTEAL = 1.15, LU = 1.15;

// P0 dot (always visible)
const dot = new THREE.Mesh(new THREE.SphereGeometry(0.095, 20, 16), new THREE.MeshBasicMaterial({ color: 0x000000 }));
dot.position.copy(P0v).addScaledVector(nOut3, 0.05); gStatic.add(dot);

/* ── surface arrow set + level circle ────────────────────────────────────── */
const levelCircle = tubeCircle(GMAG, P0.z, 0.026, COL.teal); gSurf.add(levelCircle);

const aGrad = makeArrow(LUP, COL.orange, { headLen: 0.38, headR: 0.14, shaftR: 0.054 });
placeArrow(aGrad, ORG, ascDir); gSurf.add(aGrad);
const aNeg  = makeArrow(LDN, COL.blue, { headLen: 0.36, headR: 0.135, shaftR: 0.052 });
placeArrow(aNeg, ORG, ascDir.clone().negate()); gSurf.add(aNeg);
const aTA   = makeArrow(LTEAL, COL.teal, { headLen: 0.28, headR: 0.10, shaftR: 0.04 });
placeArrow(aTA, ORG, tanDir); gSurf.add(aTA);
const aTB   = makeArrow(LTEAL, COL.teal, { headLen: 0.28, headR: 0.10, shaftR: 0.04 });
placeArrow(aTB, ORG, tanDir.clone().negate()); gSurf.add(aTB);
const aU    = makeArrow(LU, COL.purple, { headLen: 0.26, headR: 0.095, shaftR: 0.036 }); gSurf.add(aU);

// leader to P0 label
gSurf.add(lineOf([P0v, M(0.35, 3.72, 1.76)], 0x000000));

/* ── plane diagram at z = -2.0 ───────────────────────────────────────────── */
const ZP = -2.0;
const C = M(P0.x, P0.y, ZP);
const ghv = M(gh[0], gh[1], 0).normalize();
const thv = M(th_[0], th_[1], 0).normalize();
const LPG = 1.2, LPT = 0.85;

const pGrad = makeArrow(LPG, COL.orange, { headLen: 0.26, headR: 0.092, shaftR: 0.034 });
placeArrow(pGrad, C, ghv); gPlane.add(pGrad);
const pNeg = makeArrow(LPG, COL.blue, { headLen: 0.26, headR: 0.092, shaftR: 0.034 });
placeArrow(pNeg, C, ghv.clone().negate()); gPlane.add(pNeg);
const pTA = makeArrow(LPT, COL.teal, { headLen: 0.22, headR: 0.078, shaftR: 0.028 });
placeArrow(pTA, C, thv); gPlane.add(pTA);
const pTB = makeArrow(LPT, COL.teal, { headLen: 0.22, headR: 0.078, shaftR: 0.028 });
placeArrow(pTB, C, thv.clone().negate()); gPlane.add(pTB);
const pU = makeArrow(LPG * 0.8, COL.purple, { headLen: 0.22, headR: 0.08, shaftR: 0.03 }); gPlane.add(pU);

// black dot in the plane copy
const dot2 = new THREE.Mesh(new THREE.SphereGeometry(0.07, 16, 12), new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true }));
dot2.position.copy(C); gPlane.add(dot2);

// thin quadrilateral outline enclosing the flattened set
{
  const a = 1.5, b = 1.05;
  const q = [
    C.clone().addScaledVector(ghv, a).addScaledVector(thv, b),
    C.clone().addScaledVector(ghv, a).addScaledVector(thv, -b),
    C.clone().addScaledVector(ghv, -a).addScaledVector(thv, -b),
    C.clone().addScaledVector(ghv, -a).addScaledVector(thv, b)
  ];
  q.push(q[0]);
  gPlane.add(lineOf(q, 0x000000));
}
// right-angle marker between ∇f and the teal level direction
{
  const s = 0.18;
  gPlane.add(lineOf([
    C.clone().addScaledVector(ghv, s),
    C.clone().addScaledVector(ghv, s).addScaledVector(thv, s),
    C.clone().addScaledVector(thv, s)
  ], 0x000000));
}
// leader lines for the plane labels
gPlane.add(lineOf([M(2.45, 0.42, -2.40), M(0.50, 0.86, ZP)], 0x000000));
gPlane.add(lineOf([M(2.70, 1.60, -3.38), M(1.44, 2.86, ZP + 0.02)], 0x000000));
const tipTA = C.clone().addScaledVector(thv, LPT), tipTB = C.clone().addScaledVector(thv, -LPT);
gPlane.add(lineOf([M(0.90, 4.20, -2.70), tipTA], 0x000000));
gPlane.add(lineOf([M(0.90, 4.20, -2.70), tipTB], 0x000000));

/* ── dashed drop lines ───────────────────────────────────────────────────── */
function drop(mathPt, color) {
  gDrops.add(lineOf([M(mathPt[0], mathPt[1], mathPt[2]), M(mathPt[0], mathPt[1], ZP)], color, { dashed: true }));
}
drop([P0.x, P0.y, P0.z], 0xE03030);
const tipG = [P0.x + ascM.x * LUP, P0.y + ascM.y * LUP, P0.z + ascM.z * LUP];
const tipN = [P0.x - ascM.x * LDN, P0.y - ascM.y * LDN, P0.z - ascM.z * LDN];
drop(tipG, 0xE03030);
drop(tipN, 0x999999);
drop([P0.x + th_[0] * LTEAL, P0.y + th_[1] * LTEAL, P0.z], 0x999999);
drop([P0.x - th_[0] * LTEAL, P0.y - th_[1] * LTEAL, P0.z], 0x999999);
